scripts.留书.txt:
//张如梦给张琳心的留书（假）处理在obj-ini当中

	DelCurObj();
	Say("地上有一封留书。");
	Say("琳心，我已有线索。四月初五城北树林见。<enter>              兄");
	AddGoods("Goods405_书信.ini");
	Say("独孤剑：是张兄留给琳心的信……可是琳心呢？", 8);
	Say("杨瑛：看来他们的确在此留宿。张姑娘和张少侠可能分头查找线索去了……", 39);
	Say("杨瑛：今天是四月初四，明日便是初五。既然已经知道他们明日约在城北见面，独孤大哥，你也可以放心了。明日，你便可以和他们……会合了。", 41);
	Say("独孤剑：杨姑娘……", 1);
	Say("杨瑛：独孤大哥，今天就在此休息一晚罢！", 39);
	Assign($Clue, 30);
	Memo("客栈中发现了张如梦留给张琳心的信，得知明日两人约在城北树林见面。杨瑛提议在客栈留宿一晚。");
	Return;

